 "content": "def transform(grid):
    """Collapse consecutive duplicate rows and columns in a grid."""
    rows = [list(row) for row in grid]
    if not rows:
        return []

    compressed_rows = []
    for row in rows:
        if not compressed_rows or row != compressed_rows[-1]:
            compressed_rows.append(row)

    if not compressed_rows[0]:
        return compressed_rows

    kept_columns = []
    previous_column = None
    for col in range(len(compressed_rows[0])):
        column = tuple(row[col] for row in compressed_rows)
        if previous_column is None or column != previous_column:
            kept_columns.append(col)
            previous_column = column

    return [[row[col] for col in kept_columns] for row in compressed_rows]


